// ==== Drama: primero la máscara triste; al SONREIR, la feliz ====
// AJUSTES
var SONIDO = "";            // mp3 opcional, ej. "assets/sonidos/drama.mp3" (si esta vacio suena el sonido sintetizado)
var t = 0, pop = 0, happy = false;

function switchTo(h) {
	if (h === happy) return;
	happy = h; pop = 1;
	if (window.folio) { if (SONIDO) window.folio.sfx.fileOr(SONIDO, "drama"); else window.folio.sfx.play("drama"); }
}
function smileStart() { switchTo(true); }      // sonries  -> máscara feliz
function smileEnd()   { switchTo(false); }     // dejas de sonreir -> vuelve la triste

function update(event) {
	var d = event.delta / 1000;
	t += ((happy ? 1 : 0) - t) * Math.min(1, d * 9);
	pop = Math.max(0, pop - d * 2.5);
	this.children[0].material.opacity = 1 - t;
	this.children[1].material.opacity = t;
	this.scale.setScalar(1 + Math.sin(pop * Math.PI) * 0.08);
}
